			written = { ["Back to Osi, then the two elders at the back of the burrow. {npc:260661} stands beside Osi, {npc:256660} a little north-west of them, where the recording met him. {npc:260661}'s moss grows around {area:16848}, later in this guide; {npc:256660}'s amulets come from the harpies at the {area:16867}, also later in this guide, and you bring both back here then."] = "Back to Osi, then the two elders at the back of the burrow. Suma Mossmane stands beside Osi, Thobon Sapclaw a little north-west of them, where the recording met him. Suma's moss grows around Elderwild, later in this guide; Thobon's amulets come from the harpies at the Shrine of Aviana, also later in this guide, and you bring both back here then.", ["Brie, the second kitten, plays just west of {npc:249234}'s camp."] = "Brie, the second kitten, plays just west of Johun's camp.", ["Experimental route (alpha): if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nEast from the Cradle towards the {area:16867}, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for {npc:260825}."] = "Experimental route (alpha): if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nEast from the Cradle towards the Shrine of Aviana, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for Phoebe.", ["Fill {npc:267109}'s gourd at the falls beside the bridge. Solstice, one of {npc:255683}'s kittens, plays just west of the falls: walk up to her."] = "Fill Galvinquam's gourd at the falls beside the bridge. Solstice, one of Shalla'kal's kittens, plays just west of the falls: walk up to her.", ["Fly down to {npc:260626} for {npc:249235} and {npc:256222}."] = "Fly down to Bluebell for Kaylaena and Ketharas.", ["Into the burrow for the elders, {npc:260661} and {npc:256660}."] = "Into the burrow for the elders, Suma and Thobon.", ["North to {npc:255683}, then {npc:267109} in the ruins south of her."] = "North to Shalla'kal, then Galvinquam in the ruins south of her.", ["North-east across the Cradle to {npc:249234}'s camp at the edge of {area:16866}."] = "North-east across the Cradle to Johun's camp at the edge of Dae'gun.", ["North-east into the {area:17145}: {npc:267109} rests in the ruins south of {npc:255683}, on your way."] = "North-east into the Cradle of Tranquility: Galvinquam rests in the ruins south of Shalla'kal, on your way.", ["North-east to {npc:263394}: use {npc:263406}'s eye on him to drain him, then kill him. {npc:267439}, an elite (level 61), walks this corner of {area:16866}: keep out of his way.\n{npc:267097} waits a little further north-east. His Felhound Spikes come from the Defiling Hounds, and in our only recording about one hound in ten had one: kill the hounds around him while you are here, and leave his quest if the twelve spikes are slow to come."] = "North-east to Bethra'zel: use Elaena's eye on him to drain him, then kill him. Doomguard Xarkul, an elite (level 61), walks this corner of Dae'gun: keep out of his way.\nMaerion Thaelemaches waits a little further north-east. His Felhound Spikes come from the Defiling Hounds, and in our only recording about one hound in ten had one: kill the hounds around him while you are here, and leave his quest if the twelve spikes are slow to come.", ["North-west over the shrub field to {npc:249235}'s workshop on the slope above it. {quest:91923}, an elite (level 57), patrols the field, and {npc:248709}, an elite ancient (level 56), stands in its middle: give both room. Ghansurok, an elite chimaera (level 61), prowls around the workshop itself: see where he is before you ride up to {npc:249235}."] = "North-west over the shrub field to Kaylaena Springwhisper's workshop on the slope above it. Celastrus the Bitter, an elite (level 57), patrols the field, and Sunderbark, an elite ancient (level 56), stands in its middle: give both room. Ghansurok, an elite chimaera (level 61), prowls around the workshop itself: see where he is before you ride up to Kaylaena.", ["South down the west side of the shrub field to the ancients' outpost: kill the {npc:248395} you pass for {npc:249235}. {npc:260626}, the flight mistress, waits by the outpost; {npc:248367} and {npc:265586} stand with the ancient {npc:248366}."] = "South down the west side of the shrub field to the ancients' outpost: kill the Tainted Shrubbery you pass for Kaylaena. Bluebell, the flight mistress, waits by the outpost; Hyacinth and Thylaen stand with the ancient Fraxinus.", ["South to {area:493}'s flight master (the Alliance's at the southern end of the valley, the Horde's at its south-western end) and fly to {area:2255} for {npc:249235}'s parts order."] = "South to Moonglade's flight master (the Alliance's at the southern end of the valley, the Horde's at its south-western end) and fly to Everlook for Kaylaena's parts order.", ["The Blackthorne cultists camp on the slopes north-east of the Summit (level 60, with elite Outrunners, Priests and a Courier among them: pull carefully). {npc:260674}, an elite (level 60) who leads them, stands among them: leave him be. Ghansurok, an elite chimaera (level 61), also roams the ridge north of the camps.\nUse {npc:40833}'s staff on a Pact member to strip its ward, then kill it, ten times: pick Cultists and Adepts, whom Thisalee wants dead too. The Cultists carry the kris and the Adepts the staff; the thorn seeds lie in the woods there, and the hippogryphs and chimaeras roam the slopes all around. Not finished in our recordings yet: if something here is off, tell us."] = "The Blackthorne cultists camp on the slopes north-east of the Summit (level 60, with elite Outrunners, Priests and a Courier among them: pull carefully). Ve'han Talongrasp, an elite (level 60) who leads them, stands among them: leave him be. Ghansurok, an elite chimaera (level 61), also roams the ridge north of the camps.\nUse Tiala's staff on a Pact member to strip its ward, then kill it, ten times: pick Cultists and Adepts, whom Thisalee wants dead too. The Cultists carry the kris and the Adepts the staff; the thorn seeds lie in the woods there, and the hippogryphs and chimaeras roam the slopes all around. Not finished in our recordings yet: if something here is off, tell us.", ["The Rustleaf Foxes are thick in the woods around {npc:249234}'s camp."] = "The Rustleaf Foxes are thick in the woods around Johun's camp.", ["The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and {npc:256660}'s amulets; the bangles lie in their nests, the {object:650219} in a nest on the western slope, and {npc:260826}, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine."] = "The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and Thobon's amulets; the bangles lie in their nests, the Jewel of the Horizon in a nest on the western slope, and Zarrat Wormwing, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine.", ["The moss for {npc:260661} grows around {area:16848}: by the outposts and on the slopes north of them."] = "The moss for Suma grows around Elderwild: by the outposts and on the slopes north of them.", ["The seeds and the owl eggs lie on the slopes between the Hermit's Abode and the road you came in on: search north-east up towards {npc:266803} and {npc:266802}."] = "The seeds and the owl eggs lie on the slopes between the Hermit's Abode and the road you came in on: search north-east up towards Quintus and Thark.", ["The worker {npc:244517} means is a peasant just north of her; {npc:264521} stands between them."] = "The worker Sefira means is a peasant just north of her; Daythor Brellan stands between them.", ["{npc:228216} stands between {area:2255}'s two flight masters. Her crate holds fragile cells that fizzle out in time and when knocked about: fly straight back to the {area:16853} and take it to {npc:249235} without detours or fights (about four minutes in the recording). If it fizzles out anyway, {npc:228216} fills it again."] = "Nami stands between Everlook's two flight masters. Her crate holds fragile cells that fizzle out in time and when knocked about: fly straight back to the Tainted Foothills and take it to Kaylaena without detours or fights (about four minutes in the recording). If it fizzles out anyway, Nami fills it again.", ["{npc:249051}"] = "Celastrus", ["{npc:249234}'s camp"] = "Johun's camp", ["{npc:249235}'s workshop"] = "Kaylaena's workshop", ["{npc:255683} and {npc:267109}"] = "Shalla'kal and Galvinquam", ["{npc:263394} and {npc:267097}"] = "Bethra'zel and Maerion", ["{npc:263406}, {npc:249052} and {npc:267121}"] = "Elaena, Witherbeard and Yashiro", ["{npc:264521} and {npc:244517}"] = "Daythor Brellan and Sefira", ["{quest:96796}: for {npc:249235}, on the way"] = "Woods Workshop: for Kaylaena, on the way" },
