083"] = "Clerical Quarantine", ["quest:96084"] = "Something's in the Water", ["quest:96125"] = "In Need of Relief", ["quest:96126"] = "An Ogre's Captive", ["zone:1418"] = "Badlands", ["zone:1425"] = "Hinterlands", ["zone:1434"] = "Stranglethorn Vale", ["zone:1437"] = "Wetlands", ["zone:1443"] = "Desolace", ["zone:1444"] = "Feralas", ["zone:1453"] = "Stormwind", ["zone:2548"] = "Riverglades" },
			written = { ["Back north-east to the workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Back north-east to the workshop. Sleebo's stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten.", ["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. {npc:263380}, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for Benjy (they drop Halligan's heads) and the Jumbo Crawfish in the shallows for the shells. Curly, one of Halligan's lumberjacks, is stuck on the bank just north-west of the murlocs; Robbie's hat lies on the riverbank among them; the fresh manure is in the fields of Meadowsbrook, between the river and the farm. Ghostmaw, an elite (level 42), prowls the river: if he comes your way, back off and let him pass.", ["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "East along the road towards Farholde Keep: hand Benjy his murlocs as you pass Wheeler's Grange.", ["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "East down the road to Powderfuse Port, the goblins' harbour. Friz Frazzlespark keeps a stall at the west end of the docks; Gray Dawnbright, Innkeeper Zizplink and Fimbo Greasemitz are at the inn, and Wharfmaster Whizzbuzz works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from Gritta Chumwater, the degreaser and the old poison from Kor'gar and Krikshank, by Friz's stall.", ["Free him, then get him out: {npc:259057} fights his way out of {area:16726}, and you keep the ogres off him. If he falls, take the quest from him again."] = "Free him, then get him out: Dunston fights his way out of Bolder'ok, and you keep the ogres off him. If he falls, take the quest from him again.", ["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42), Komuk (a Horde elite, 45) and {npc:263380} (elite, 42) range over the zone's wilds: take your beasts away from them."] = "Most beasts in the Riverglades drop Beast Entrails for Argo: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: Old Rot-Chum (elite, 42), Komuk (a Horde elite, 45) and Ghostmaw (elite, 42) range over the zone's wilds: take your beasts away from them.", ["North along the beach from the docks: the crawlers drop the meat for {npc:259962} and the spittle for Zizplink, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "North along the beach from the docks: the crawlers drop the meat for Fimbo and the spittle for Zizplink, and their entrails count for Argo. Trapclaw, a big crab, scuttles along the rocks east of the docks. Gul'gash, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away.", ["North-east across the fields to {area:16725}: {npc:258317} wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads {npc:256438} needs, so one pass along the river does both."] = "North-east across the fields to Wheeler's Grange: Benjy Wheeler wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads Halligan needs, so one pass along the river does both.", ["South-west across the plains to {area:16724}. {npc:257591} and {npc:257558} stand together in the keep at the east end: {npc:257591} first, her news is what Brant's next orders wait on."] = "South-west across the plains to Farholde Keep. Ashe Amberhall and Demar Brant stand together in the keep at the east end: Ashe first, her news is what Brant's next orders wait on.", ["The cult's camps fill the valley north and west of Riftan. Free the captive Farholde Scouts as you find them, and kill a {npc:258652} for {npc:257591}: her soulstone takes it. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them."] = "The cult's camps fill the valley north and west of Riftan. Free the captive Farholde Scouts as you find them, and kill a Twilight Thrall for Ashe: her soulstone takes it. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. Overlord Kilgar and Executioner Morg (elites, 46) hold the fortress at the valley's head: pull the cultists away from them.", ["Use {npc:256438}'s {item:266161} on bare ground around the camp: five saplings."] = "Use Halligan's Tree Sprouting Kit on bare ground around the camp: five saplings.", ["West of the port, the wildflowers grow in the meadows below {npc:263367}'s workshop."] = "West of the port, the wildflowers grow in the meadows below Sleebo's workshop.", ["help {npc:259057} break out of {area:16726}"] = "help Dunston break out of Bolder'ok", ["{npc:263367}'s workshop"] = "Sleebo's workshop", ["{npc:263749} (level 44) carries the key: he paces the lanes south of {npc:259057}'s hut.\nThe {item:275043} lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be."] = "Gronok the Butcher (level 44) carries the key: he paces the lanes south of Dunston's hut.\nThe Bloodmaster's Ring lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be.", ["{quest:95984}: for later, where the tallstriders graze by {npc:263367}'s workshop; keep it"] = "Song of the Strider: for later, where the tallstriders graze by Sleebo's workshop; keep it" },
